code.regionString:
%{
disp("Составляющие B по отдельным компонентам (bx,by,bz)");
num_ro = fn_rox(bx,r_in(1,:),r_in(2,:),r_in(3,:));
RO = mean(num_ro(1,:))

fg_alsobx = figure("Name","also_Bx");
plot(r_in(1,:),bx);
grid on; grid minor;
hold on
X = -29e-2:1e-2:29e-2;
N = size(X,2);
bx_aprox = fn_Bx(repelem(RO,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
plot(X,bx_aprox,"--");
%clear N X
legend("B_x","fn_{Bx}")
hold off


num_ro = fn_roy(by,r_in(1,:),r_in(2,:),r_in(3,:));
RO = mean(num_ro(1,:))

fg_alsoby = figure("Name","also_By");
plot(r_in(1,:),by);
grid on; grid minor;
hold on
%X = -29e-2:1e-2:29e-2;
%N = size(X,2);
by_aprox = fn_By(repelem(RO,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
plot(X,by_aprox,"--");
%clear N X
legend("B_y","fn_{By}")
hold off


num_ro = fn_roz(bz,r_in(1,:),r_in(2,:),r_in(3,:));
RO = mean(num_ro(1,:))

fg_alsobz = figure("Name","also_Bz");
plot(r_in(1,:),bz);
grid on; grid minor;
hold on
%X = -29e-2:1e-2:29e-2;
%N = size(X,2);
bz_aprox = fn_Bz(repelem(RO,N),X,repelem(r_in(2,1),N),repelem(r_in(3,1),N));
plot(X,bz_aprox,"--");
legend("B_z","fn_{Bz}")
hold off
%--
%}
